/*
 * NET_IO_$SEND - Send a packet on a network port
 *
 * Original address: 0x00E0E692 (SAU2 map: NET_IO_$SEND at E0E692)
 * Size: 560 bytes (0x00E0E692 .. 0x00E0E8C1); its RINGLOG header-info
 * cell follows at 0x00E0E8C2.
 * Generated by: Claude Opus 5.5
 *
 * Frame (link.w A6,-0x34; D2-D5/A2-A5 saved; A5 = 0xE244F0, the NET_IO
 * data, whose first longword is NET_IO_$ALL_F_ADDR):
 *   (0x08,A6) port        word (D0w), index into ROUTE_$PORTP
 *   (0x0A,A6) hdr_ptr     -> the header VA (D3)
 *   (0x0E,A6) hdr_pa, (0x12,A6) hdr_len word, (0x14,A6) data_va,
 *   (0x18,A6) data_pages (D4), (0x1C,A6) data_len word,
 *   (0x1E,A6) flags       word, handed to the driver BY ADDRESS
 *   (0x20,A6) send_info (D5), (0x24,A6) status (A3)
 *   (-0x10) copy_pages[4], (-0x14) deliver_out, (-0x20) copy_hdr,
 *   (-0x24) drv_status; D2w the RINGLOG entry index.
 *
 * Blocks:
 *   0x00E0E6B4-0x00E0E6F6  port range 0..7, then the port must be open
 *                          (active 0 -> "network port not open", 1 ->
 *                          "request denied by local node")
 *   0x00E0E6FA-0x00E0E764  a packet for this node: copy it into fresh
 *                          buffers and deliver it to ROUTE_$PORT_ARRAY[0]'s
 *                          socket; send_info = {0, |0x8008}
 *   0x00E0E768-0x00E0E828  an internet packet: refuse an all-ones source
 *                          node; on this port's network (or network 0) an
 *                          all-ones destination becomes a broadcast
 *                          (dest_node 0, info bit 7) that is also delivered
 *                          locally when protocol byte +0x2C is set; off the
 *                          network a broadcast flag is turned back into an
 *                          all-ones destination node
 *   0x00E0E82C-0x00E0E8B6  send_info = {port type, 0}; count the packet; log
 *                          it; call the driver's sendp (nil: status 0); put
 *                          the transmit status into the log entry
 *
 * Quirks reproduced:
 *   - The loopback path leaves *status as NET_IO_$COPY_PACKET set it and
 *     ORs 0x8008 into xmit_status without clearing it first.
 *   - A local-delivery copy of a broadcast is made even when it will also
 *     be transmitted, and its failure is ignored (*status is cleared at
 *     0x00E0E836).
 */

#include "net_io/net_io_internal.h"
#include "node/node.h"
#include "network/network.h"
#include "pkt/pkt.h"
#include "ring/ringlog.h"

/* Ports: `cmpi.w #0x7` 0x00E0E6B8 */
#define NET_IO_SEND_MAX_PORT        7

/* route_$port_t.active values refused (0x00E0E6D8, 0x00E0E6E8) */
#define NET_IO_PORT_CLOSED          0
#define NET_IO_PORT_LOCAL_ONLY      1

/* pkt_$hdr_t.routing_type of a local packet (0x00E0E76E) */
#define NET_IO_ROUTING_LOCAL        1

/* pkt_$hdr_t.info_flags bit 7: broadcast */
#define NET_IO_INFO_BROADCAST       0x80

/* The node bits compared with NET_IO_$ALL_F_ADDR */
#define NET_IO_NODE_MASK            0x00FFFFFFu

/* The loopback's xmit_status bits: `ori.w #-0x7ff8` 0x00E0E75E */
#define NET_IO_XMIT_LOOPBACK        0x8008

/*
 * The header-info cell handed to RINGLOG_$LOGIT (`pea (0x78,PC)` at
 * 0x00E0E848 = 0x00E0E8C2, bytes 00 00): bit 7 of byte 0 clear, i.e. an
 * outbound packet.
 */
static const uint8_t net_io_$send_ringlog_info[2] = { 0x00, 0x00 };

void NET_IO_$SEND(int16_t port, uint32_t *hdr_ptr, uint32_t hdr_pa,
                  uint16_t hdr_len, uint32_t data_va, uint32_t *data_pages,
                  int16_t data_len, uint16_t flags,
                  net_io_$send_info_t *send_info, status_$t *status_ret)
{
    uint32_t copy_pages[4];             /* (-0x10,A6) */
    uint32_t deliver_out;               /* (-0x14,A6) */
    uint32_t copy_hdr;                  /* (-0x20,A6) */
    status_$t drv_status;               /* (-0x24,A6) */
    route_$port_t *p;                   /* A2 */
    pkt_$hdr_t *hdr;                    /* A4 */
    net_io_$driver_t *drv;              /* A4 */
    int16_t log_index;                  /* D2w */

    /* 0x00E0E6B4-0x00E0E6F6 */
    if (port < 0 || port > NET_IO_SEND_MAX_PORT) {
        *status_ret = status_$internet_unknown_network_port;
        return;
    }
    p = ROUTE_$WIRED_DATA.portp[port];
    if (p->active == NET_IO_PORT_CLOSED) {
        *status_ret = status_$internet_network_port_not_open;
        return;
    }
    if (p->active == NET_IO_PORT_LOCAL_ONLY) {
        *status_ret = status_$network_request_denied_by_local_node;
        return;
    }

    hdr = (pkt_$hdr_t *)ARCH_VA_TO_PTR(*hdr_ptr);
    if (hdr->dest_node == NODE_$ME) {
        /* 0x00E0E708-0x00E0E764: loopback */
        NET_IO_$COPY_PACKET(hdr_ptr, hdr_len, data_va, data_pages,
                            (uint16_t)data_len, &copy_hdr, copy_pages,
                            status_ret);
        if (*status_ret == status_$ok) {
            p = &ROUTE_$PORT_ARRAY[0];                    /* #0xe2e0a0 */
            net_io_$put_in_sock_common(p, p->port_type, p->socket, 0,
                                       &copy_hdr, copy_pages, hdr_len,
                                       (uint16_t)data_len, &deliver_out);
        }
        send_info->port_net = 0;
        send_info->xmit_status |= NET_IO_XMIT_LOOPBACK;
        return;
    }

    if (hdr->routing_type != NET_IO_ROUTING_LOCAL) {
        /* 0x00E0E776-0x00E0E790 */
        if ((hdr->u.inet.src.node & NET_IO_NODE_MASK & NET_IO_$ALL_F_ADDR) ==
            NET_IO_$ALL_F_ADDR) {
            *status_ret = status_$network_transmit_with_invalid_from_id;
            return;
        }

        if (hdr->u.inet.dest.net == p->network || hdr->u.inet.dest.net == 0) {
            /* 0x00E0E79E-0x00E0E816 */
            if ((hdr->u.inet.dest.node & NET_IO_NODE_MASK & NET_IO_$ALL_F_ADDR) ==
                NET_IO_$ALL_F_ADDR) {
                hdr->dest_node = 0;
                hdr->info_flags |= NET_IO_INFO_BROADCAST;
            }
            if (hdr->u.inet.info_0b != 0 &&
                (hdr->info_flags & NET_IO_INFO_BROADCAST) != 0) {
                NET_IO_$COPY_PACKET(hdr_ptr, hdr_len, data_va, data_pages,
                                    (uint16_t)data_len, &copy_hdr, copy_pages,
                                    status_ret);
                if (*status_ret == status_$ok) {
                    net_io_$put_in_sock_common(p, p->port_type, p->socket, 0,
                                               &copy_hdr, copy_pages, hdr_len,
                                               (uint16_t)data_len, &deliver_out);
                }
            }
        } else if ((hdr->info_flags & NET_IO_INFO_BROADCAST) != 0) {
            /* 0x00E0E818-0x00E0E828 */
            hdr->info_flags &= (uint8_t)~NET_IO_INFO_BROADCAST;
            hdr->u.inet.dest.node |= NET_IO_NODE_MASK;
        }
    }

    /* 0x00E0E82C-0x00E0E858 */
    send_info->port_net = p->port_type;
    send_info->xmit_status = 0;
    *status_ret = status_$ok;
    p->forward_count++;
    if (RINGLOG_$CTL.logging_active < 0) {
        log_index = RINGLOG_$LOGIT(net_io_$send_ringlog_info,
                                   ARCH_VA_TO_PTR(*hdr_ptr));
    } else {
        log_index = -1;
    }

    /* 0x00E0E85A-0x00E0E89C */
    drv = (net_io_$driver_t *)ARCH_VA_TO_PTR(p->driver_info);
    if (drv->sendp == NULL) {
        drv_status = status_$ok;
    } else {
        ((net_io_$sendp_fn_t)drv->sendp)(&p->socket, hdr_pa,
                                         ARCH_VA_TO_PTR(*hdr_ptr), hdr_len,
                                         data_pages, data_va,
                                         (uint16_t)data_len, &flags,
                                         &send_info->xmit_status,
                                         &drv_status);
    }
    *status_ret = drv_status;

    /* 0x00E0E8A0-0x00E0E8B2: the entry's last packet word, entry + 0x2E */
    if (log_index != -1) {
        *(uint16_t *)(void *)&RINGLOG_$DATA.bytes[(int32_t)log_index *
                                                  RINGLOG_ENTRY_SIZE +
                                                  RINGLOG_ENTRY_SIZE] =
            send_info->xmit_status;
    }
}
